import java.util.*;

class Solution {
  public List<Integer> cheapestJump(int[] coins, int maxJump) {
    int n = coins.length;
    long[] cost = new long[n]; // cheapest cost from i to the end
    int[] next = new int[n];
    Arrays.fill(cost, Long.MAX_VALUE);
    Arrays.fill(next, -1);
    if (coins[n - 1] != -1) cost[n - 1] = coins[n - 1];
    // going backwards and taking the first cheapest jump gives the lexicographically smallest path
    for (int i = n - 2; i >= 0; i--) {
      if (coins[i] == -1) continue;
      for (int j = i + 1; j <= Math.min(n - 1, i + maxJump); j++) {
        if (cost[j] == Long.MAX_VALUE) continue;
        if (coins[i] + cost[j] < cost[i]) {
          cost[i] = coins[i] + cost[j];
          next[i] = j;
        }
      }
    }
    List<Integer> path = new ArrayList<>();
    if (cost[0] == Long.MAX_VALUE) return path;
    for (int i = 0; i != -1; i = next[i]) path.add(i + 1);
    return path;
  }
}
